import { createHash } from 'node:crypto';
import { z } from 'zod';
import type { CLIHandler, CLIQuestionRequest, CLIQuestions, TerminalId } from '@multi-cc-im/shared';
import { formatErrorWithCause } from '@multi-cc-im/shared';
import { codexHome, connectCodexLocal, listLoadedCodexThreads, type CodexLocalClient } from './local-client.js';
import { codexRuntimeError } from './app-server-protocol.js';

// Generated by Codex 0.163.0 `app-server generate-json-schema`.
const QuestionParams = z.object({
  threadId: z.string().min(1), turnId: z.string().min(1), itemId: z.string().min(1),
  isBlocking: z.boolean(), autoResolutionMs: z.number().nonnegative().nullable().optional(),
  questions: z.array(z.object({ id: z.string().min(1), header: z.string(), question: z.string(),
    isOther: z.boolean().optional(), isSecret: z.boolean().optional(),
    options: z.array(z.object({ label: z.string().min(1), description: z.string() })).nullable().optional(),
  })).min(1).refine(qs => new Set(qs.map(q => q.id)).size === qs.length),
});
const SessionSource = z.union([z.enum(['cli', 'vscode', 'exec', 'appServer', 'unknown']), z.object({ custom: z.string() }), z.object({ subAgent: z.union([z.string(), z.record(z.unknown())]) })]);
const Thread = z.object({ thread: z.object({ id: z.string(), name: z.string().nullish(), source: SessionSource, status: z.object({ type: z.string() }) }) });
const Resolved = z.object({ threadId: z.string(), requestId: z.union([z.string(), z.number().int()]) });
const Completed = z.object({ threadId: z.string(), turn: z.object({ id: z.string() }) });


/** Native question discovery uses current session names in one configured home. */
export interface CodexQuestionClientOpts {
  terminalId: TerminalId;
  /** Explicit home for isolated tests; production uses CODEX_HOME or ~/.codex. */
  home?: string;
  /** Nonfatal diagnostics; never restarts or terminates a user's TUI. */
  onError(err: unknown): void;
  intervalMs?: number;
  rpcTimeoutMs?: number;
}

/** Question capability plus ownership of this client's local socket only. */
export interface CodexQuestionClient extends CLIQuestions {
  /** Start discovery; does not wait for a native server to become available. */
  start(handler: CLIHandler): Promise<void>;
  /** Disconnect this observer and discard pending answer availability. */
  stop(): Promise<void>;
}
interface Binding { sessionName: string; ready: boolean }
interface Pending { request: CLIQuestionRequest; submitted: boolean }

/**
 * Observe native questions on uniquely named loaded root sessions.
 * @param opts Selected home, IM mode scope and bounded lifecycle dependencies.
 * @returns Native question capability; no TUI stdin or process ownership.
 * @example const questions = createCodexQuestionClient({ terminalId, onError });
 */
export function createCodexQuestionClient(opts: CodexQuestionClientOpts): CodexQuestionClient {
  const home = opts.home ?? codexHome();
  const bindings = new Map<string, Binding>(), pending = new Map<string, Pending>();
  const tasks = new Set<Promise<void>>();
  let handler: CLIHandler = { async onPreToolUse() {}, async onStop() {} };
  let running = false, client: CodexLocalClient | undefined;
  let timer: NodeJS.Timeout | undefined, refreshing: Promise<void> | undefined;
  let lastDiagnostic: string | undefined;

  function diagnostic(err: unknown): void {
    const text = formatErrorWithCause(err);
    if (text !== lastDiagnostic) { lastDiagnostic = text; opts.onError(err); }
  }
  function report(task: Promise<void> | undefined): void {
    if (!task) return;
    const guarded = task.catch(diagnostic).finally(() => tasks.delete(guarded));
    tasks.add(guarded);
  }
  function closeRequest(ref: string, reason: 'resolved' | 'disconnected' | 'replaced'): void {
    if (pending.delete(ref)) report(handler.onQuestionClosed?.(ref, reason));
  }
  function dropThread(threadId: string, reason: 'resolved' | 'replaced'): void {
    for (const [ref, entry] of pending) if (entry.request.threadId === threadId) closeRequest(ref, reason);
    bindings.delete(threadId);
  }
  function disconnected(): void {
    client = undefined; bindings.clear();
    for (const ref of pending.keys()) closeRequest(ref, 'disconnected');
  }
  async function deliver(ref: string): Promise<void> {
    await refresh();
    const entry = pending.get(ref);
    if (entry && bindings.get(entry.request.threadId)?.ready) await handler.onQuestion?.(entry.request);
  }
  function receive(id: string | number | undefined, method: string, params: unknown): void {
    if (method === 'item/tool/requestUserInput' && id !== undefined) {
      const parsed = QuestionParams.safeParse(params);
      if (!parsed.success) { diagnostic(codexRuntimeError(method, client?.version ?? 'unknown', parsed.error)); return; }
      const p = parsed.data, binding = bindings.get(p.threadId);
      if (!binding) return;
      const reference = 'codex-' + createHash('sha256').update(JSON.stringify([home, p.threadId, p.turnId, p.itemId, id])).digest('hex').slice(0, 24);
      if (pending.has(reference)) return;
      const request: CLIQuestionRequest = { reference, ...p, requestId: id, termId: opts.terminalId, sessionName: binding.sessionName };
      pending.set(reference, { request, submitted: false });
      report(deliver(reference));
    } else if (method === 'serverRequest/resolved') {
      const p = Resolved.safeParse(params);
      if (!p.success) return;
      for (const [ref, entry] of pending) if (entry.request.threadId === p.data.threadId && entry.request.requestId === p.data.requestId) closeRequest(ref, 'resolved');
    } else if (method === 'turn/completed') {
      const p = Completed.safeParse(params);
      if (!p.success) return;
      for (const [ref, entry] of pending) if (entry.request.threadId === p.data.threadId && entry.request.turnId === p.data.turn.id) closeRequest(ref, 'resolved');
    } else if (method === 'thread/closed') {
      const p = z.object({ threadId: z.string() }).safeParse(params);
      if (p.success) dropThread(p.data.threadId, 'resolved');
    }
  }
  async function doRefresh(): Promise<void> {
    const peer: CodexLocalClient = client ??= connectCodexLocal({ home, timeoutMs: opts.rpcTimeoutMs, onEvent: receive,
      onError: diagnostic, onDisconnect: () => { if (client === peer) disconnected(); } });
    await peer.ready;
    const loaded = await listLoadedCodexThreads(peer);
    const named = new Map<string, string>();
    const counts = new Map<string, number>();
    for (const threadId of new Set(loaded)) {
      if (!running || peer !== client) return;
      try {
        const { thread } = Thread.parse(await peer.call('thread/read', { threadId, includeTurns: false }));
        if (thread.id !== threadId) throw new Error('Codex thread identity mismatch');
        if (!['idle', 'active'].includes(thread.status.type) || (typeof thread.source === 'object' && 'subAgent' in thread.source)) continue;
        if (!thread.name?.trim()) {
          diagnostic(new Error(`Codex session ${threadId} has no name; use /rename <session-name> in that session to forward native questions.`));
          continue;
        }
        named.set(threadId, thread.name);
        counts.set(thread.name, (counts.get(thread.name) ?? 0) + 1);
      } catch (err) { diagnostic(codexRuntimeError('thread/read', peer.version, err)); }
    }
    if (!running || peer !== client) return;
    for (const [name, count] of counts) {
      if (count > 1) diagnostic(new Error(`Codex session name ${JSON.stringify(name)} is duplicated; use /rename to give the sessions distinct names. Native question forwarding for this name is paused.`));
    }
    const selected = new Map([...named].filter(([, name]) => counts.get(name) === 1));
    for (const [threadId, binding] of bindings) {
      const name = selected.get(threadId);
      if (name === undefined) {
        dropThread(threadId, 'replaced');
        await peer.call('thread/unsubscribe', { threadId });
      } else if (binding.sessionName !== name) {
        binding.sessionName = name;
        for (const entry of pending.values()) {
          // The bridge retains this request object for completion notifications.
          if (entry.request.threadId === threadId) entry.request.sessionName = name;
        }
      }
    }
    for (const [threadId, sessionName] of selected) {
      if (!running || peer !== client) return;
      if (bindings.has(threadId)) continue;
      const binding: Binding = { sessionName, ready: false };
      bindings.set(threadId, binding);
      try {
        const resumed = z.object({ thread: z.object({ id: z.string() }) }).parse(await peer.call('thread/resume', { threadId, excludeTurns: true }));
        if (resumed.thread.id !== threadId) throw new Error('Codex resumed thread identity mismatch');
        if (running && client === peer && bindings.get(threadId) === binding) binding.ready = true;
      } catch (err) { dropThread(threadId, 'replaced'); diagnostic(codexRuntimeError('thread/resume', peer.version, err)); }
    }
  }
  function refresh(): Promise<void> {
    if (!refreshing) refreshing = doRefresh().catch(err => {
      if (running) diagnostic(err);
      const peer = client; disconnected(); peer?.close();
    }).finally(() => { refreshing = undefined; });
    return refreshing;
  }
  async function tick(): Promise<void> {
    await refresh();
    if (running) { timer = setTimeout(() => { void tick(); }, opts.intervalMs ?? 2000); timer.unref(); }
  }
  return {
    async start(h) { if (running) throw new Error('Codex question client already started'); handler = h; running = true; void tick(); },
    async stop() {
      running = false; clearTimeout(timer); client?.close();
      await refreshing; await Promise.all(tasks);
    },
    refresh,
    listPending() { return [...pending.values()].filter(e => !e.submitted && bindings.get(e.request.threadId)?.ready).map(e => e.request); },
    async answer(reference, answers) {
      const entry = pending.get(reference);
      if (!entry) return 'resolved';
      const keys = Object.keys(answers), qs = entry.request.questions;
      if (qs.some(q => q.isSecret) || keys.length !== qs.length || qs.some(q => {
        const a = answers[q.id];
        return !Object.hasOwn(answers, q.id) || !a || a.length !== 1 || !a[0]?.trim();
      })) return 'invalid';
      if (!running) return 'unavailable';
      await refresh();
      if (pending.get(reference) !== entry) return client ? 'resolved' : 'unavailable';
      if (entry.submitted) return 'resolved';
      if (!client || !bindings.get(entry.request.threadId)?.ready) return 'unavailable';
      entry.submitted = true;
      const nativeAnswers = Object.fromEntries(qs.map(q => [q.id, { answers: [...answers[q.id]!] }]));
      try { await client.respond(entry.request.requestId, { answers: nativeAnswers }); return 'submitted'; }
      catch (err) { diagnostic(err); client?.close(); return 'unavailable'; }
    },
  };
}
